import os
from typing import Dict, List, Any, Optional

from azure.core.credentials import AzureKeyCredential
from azure.ai.formrecognizer import DocumentAnalysisClient


def _normalize_text(value: Optional[str]) -> str:
    if value is None:
        return ""
    return str(value).strip()


def _field_value_to_text(field: Any) -> str:
    if field is None:
        return ""

    value = getattr(field, "value", None)
    if value is not None:
        if isinstance(value, list):
            parts = []
            for item in value:
                item_content = getattr(item, "content", None)
                if item_content:
                    parts.append(str(item_content).strip())
                else:
                    parts.append(str(item).strip())
            return " ".join(p for p in parts if p)
        return _normalize_text(value)

    content = getattr(field, "content", None)
    if content:
        return _normalize_text(content)

    return _normalize_text(field)


def extract_key_value_pairs(
    file_path: str,
    endpoint: Optional[str] = None,
    api_key: Optional[str] = None,
) -> Dict[str, Any]:
    endpoint = endpoint or os.environ["AZURE_FORM_RECOGNIZER_ENDPOINT"]
    api_key = api_key or os.environ["AZURE_FORM_RECOGNIZER_KEY"]

    client = DocumentAnalysisClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(api_key),
    )

    with open(file_path, "rb") as f:
        poller = client.begin_analyze_document(
            model_id="prebuilt-document",
            document=f,
        )
    result = poller.result()

    key_value_pairs: List[Dict[str, str]] = []
    flat_pairs: Dict[str, str] = {}

    for kv in getattr(result, "key_value_pairs", []) or []:
        key_text = _normalize_text(getattr(getattr(kv, "key", None), "content", None))
        value_text = _normalize_text(getattr(getattr(kv, "value", None), "content", None))

        if not key_text:
            continue

        key_value_pairs.append({"key": key_text, "value": value_text})

        if key_text in flat_pairs:
            i = 2
            candidate = f"{key_text}_{i}"
            while candidate in flat_pairs:
                i += 1
                candidate = f"{key_text}_{i}"
            flat_pairs[candidate] = value_text
        else:
            flat_pairs[key_text] = value_text

    documents_data: List[Dict[str, str]] = []
    for doc in getattr(result, "documents", []) or []:
        fields = getattr(doc, "fields", {}) or {}
        normalized_fields: Dict[str, str] = {}
        for name, field in fields.items():
            normalized_fields[str(name)] = _field_value_to_text(field)
        if normalized_fields:
            documents_data.append(normalized_fields)

    return {
        "provider": "Azure AI Document Intelligence",
        "model_id": "prebuilt-document",
        "key_value_pairs": key_value_pairs,
        "fields": flat_pairs,
        "documents": documents_data,
        "page_count": len(getattr(result, "pages", []) or []),
        "content": _normalize_text(getattr(result, "content", None)),
    }
